#!/usr/bin/env python3
from __future__ import annotations

import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def write(rel: str, text: str) -> None:
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8", newline="\n")

write("packaging/npm/lib/runtime.js", '"use strict";\n\nconst crypto = require("node:crypto");\nconst fs = require("node:fs");\nconst https = require("node:https");\nconst os = require("node:os");\nconst path = require("node:path");\nconst { spawnSync } = require("node:child_process");\nconst { version } = require("../package.json");\n\nconst PACKAGE = "japan-career-agent";\nconst SPEC = `${PACKAGE}==${version}`;\nconst UV_VERSION = "0.12.7";\nconst MAX_ARCHIVE_BYTES = 40 * 1024 * 1024;\nconst PACKAGE_ROOT = path.resolve(__dirname, "..");\nconst RUNTIME_ROOT = path.join(PACKAGE_ROOT, ".runtime");\nconst UV_DIR = path.join(RUNTIME_ROOT, "uv");\nconst TOOL_DIR = path.join(RUNTIME_ROOT, "tools");\nconst TOOL_BIN_DIR = path.join(RUNTIME_ROOT, "bin");\nconst PYTHON_DIR = path.join(RUNTIME_ROOT, "python");\nconst CACHE_DIR = path.join(RUNTIME_ROOT, "cache");\nconst MARKER = path.join(RUNTIME_ROOT, "install.json");\n\nconst UV_ARCHIVES = Object.freeze({\n  "darwin-arm64": {\n    asset: "uv-aarch64-apple-darwin.tar.gz",\n    sha256: "127ebdda7ad953cdf198e964b570ea5771b85467ea93eb7cb6d6f8e6f55408f3",\n  },\n  "darwin-x64": {\n    asset: "uv-x86_64-apple-darwin.tar.gz",\n    sha256: "06b8ae1da8c2661c5434507a66f8c2b0b835933bf955b5958a9ac357a37d1959",\n  },\n  "win32-arm64": {\n    asset: "uv-aarch64-pc-windows-msvc.zip",\n    sha256: "1611d0f4be72b0a354ad9a6ae954093dd4c91e93e36b8b490326a05a039ffe14",\n  },\n  "win32-x64": {\n    asset: "uv-x86_64-pc-windows-msvc.zip",\n    sha256: "bf1518af459a3915511a11fdc6e2f43ef9a2afa138b9d498eeb9642fe9d85218",\n  },\n  "linux-arm64-gnu": {\n    asset: "uv-aarch64-unknown-linux-gnu.tar.gz",\n    sha256: "66393193038dd7eb108abd7a218d9cec04ac70ab98242b0720fa94de19223b7c",\n  },\n  "linux-x64-gnu": {\n    asset: "uv-x86_64-unknown-linux-gnu.tar.gz",\n    sha256: "788f18abea7c5f55d6216e4f5613fd89d4d59b631efeec117b2b07fe72f1da21",\n  },\n  "linux-arm64-musl": {\n    asset: "uv-aarch64-unknown-linux-musl.tar.gz",\n    sha256: "6dcf60e3c085de88ace3671b949ca99f0652be561ff5627f0d21394140f041db",\n  },\n  "linux-x64-musl": {\n    asset: "uv-x86_64-unknown-linux-musl.tar.gz",\n    sha256: "3d64d44ed67da7908dc7f5c4d64ebb44bad326fa17f8a0a52fc9a7793017bbe1",\n  },\n});\n\nfunction isMusl() {\n  if (process.platform !== "linux") return false;\n  try {\n    const report = process.report?.getReport?.();\n    return !report?.header?.glibcVersionRuntime;\n  } catch {\n    return false;\n  }\n}\n\nfunction platformKey() {\n  if (!["x64", "arm64"].includes(process.arch)) {\n    throw new Error(`unsupported CPU architecture: ${process.arch}`);\n  }\n  if (process.platform === "linux") {\n    return `linux-${process.arch}-${isMusl() ? "musl" : "gnu"}`;\n  }\n  if (process.platform === "darwin" || process.platform === "win32") {\n    return `${process.platform}-${process.arch}`;\n  }\n  throw new Error(`unsupported platform: ${process.platform}`);\n}\n\nfunction platformArchive() {\n  const key = platformKey();\n  const archive = UV_ARCHIVES[key];\n  if (!archive) throw new Error(`no pinned uv archive for ${key}`);\n  return archive;\n}\n\nfunction allowedDownloadHost(hostname) {\n  return hostname === "github.com" ||\n    hostname === "release-assets.githubusercontent.com" ||\n    hostname === "objects.githubusercontent.com" ||\n    hostname.endsWith(".githubusercontent.com");\n}\n\nfunction fetchBuffer(url, redirects = 0) {\n  return new Promise((resolve, reject) => {\n    if (redirects > 5) {\n      reject(new Error("too many redirects while downloading uv"));\n      return;\n    }\n    const parsed = new URL(url);\n    if (parsed.protocol !== "https:" || !allowedDownloadHost(parsed.hostname)) {\n      reject(new Error(`refusing uv download from ${parsed.origin}`));\n      return;\n    }\n    const request = https.get(parsed, {\n      headers: { "User-Agent": `${PACKAGE}/${version}` },\n    }, (response) => {\n      const status = response.statusCode || 0;\n      if (status >= 300 && status < 400 && response.headers.location) {\n        const next = new URL(response.headers.location, parsed);\n        response.resume();\n        fetchBuffer(next.toString(), redirects + 1).then(resolve, reject);\n        return;\n      }\n      if (status !== 200) {\n        response.resume();\n        reject(new Error(`uv download returned HTTP ${status}`));\n        return;\n      }\n      const declared = Number(response.headers["content-length"] || 0);\n      if (declared > MAX_ARCHIVE_BYTES) {\n        response.resume();\n        reject(new Error(`uv archive exceeds ${MAX_ARCHIVE_BYTES} bytes`));\n        return;\n      }\n      const chunks = [];\n      let received = 0;\n      response.on("data", (chunk) => {\n        received += chunk.length;\n        if (received > MAX_ARCHIVE_BYTES) {\n          request.destroy(new Error(`uv archive exceeds ${MAX_ARCHIVE_BYTES} bytes`));\n          return;\n        }\n        chunks.push(chunk);\n      });\n      response.on("end", () => resolve(Buffer.concat(chunks)));\n    });\n    request.on("error", reject);\n    request.setTimeout(60_000, () => request.destroy(new Error("uv download timed out")));\n  });\n}\n\nfunction run(command, args, options = {}) {\n  const result = spawnSync(command, args, {\n    stdio: options.stdio || "inherit",\n    shell: false,\n    env: options.env || process.env,\n    encoding: options.encoding,\n  });\n  if (result.error) {\n    throw new Error(`could not start ${command}: ${result.error.message}`);\n  }\n  if (result.status !== 0) {\n    throw new Error(`${command} exited with status ${result.status}`);\n  }\n  return result;\n}\n\nfunction findUv(root) {\n  const wanted = process.platform === "win32" ? "uv.exe" : "uv";\n  const stack = [root];\n  while (stack.length) {\n    const current = stack.pop();\n    for (const entry of fs.readdirSync(current, { withFileTypes: true })) {\n      const candidate = path.join(current, entry.name);\n      if (entry.isDirectory()) stack.push(candidate);\n      else if (entry.isFile() && entry.name === wanted) return candidate;\n    }\n  }\n  throw new Error(`pinned uv archive did not contain ${wanted}`);\n}\n\nfunction extractArchive(archivePath, destination, asset) {\n  fs.mkdirSync(destination, { recursive: true });\n  if (asset.endsWith(".zip")) {\n    const script = "$ErrorActionPreference=\'Stop\'; Expand-Archive -LiteralPath $env:JCA_ARCHIVE -DestinationPath $env:JCA_DEST -Force";\n    const env = { ...process.env, JCA_ARCHIVE: archivePath, JCA_DEST: destination };\n    const powershell = process.env.ComSpec ? "powershell.exe" : "powershell";\n    run(powershell, ["-NoProfile", "-NonInteractive", "-Command", script], { env });\n    return;\n  }\n  run("tar", ["-xzf", archivePath, "-C", destination]);\n}\n\nfunction privateUvPath() {\n  return path.join(UV_DIR, process.platform === "win32" ? "uv.exe" : "uv");\n}\n\nasync function installUv() {\n  const archive = platformArchive();\n  const url = `https://github.com/astral-sh/uv/releases/download/${UV_VERSION}/${archive.asset}`;\n  const bytes = await fetchBuffer(url);\n  const digest = crypto.createHash("sha256").update(bytes).digest("hex");\n  if (digest !== archive.sha256) {\n    throw new Error(`uv checksum mismatch for ${archive.asset}`);\n  }\n\n  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), "japan-career-uv-"));\n  try {\n    const archivePath = path.join(temporary, archive.asset);\n    const extracted = path.join(temporary, "extracted");\n    fs.writeFileSync(archivePath, bytes, { mode: 0o600 });\n    extractArchive(archivePath, extracted, archive.asset);\n    const source = findUv(extracted);\n    fs.mkdirSync(UV_DIR, { recursive: true });\n    const target = privateUvPath();\n    fs.copyFileSync(source, target);\n    if (process.platform !== "win32") fs.chmodSync(target, 0o755);\n    return target;\n  } finally {\n    fs.rmSync(temporary, { recursive: true, force: true });\n  }\n}\n\nfunction uvVersionMatches(uv) {\n  const result = spawnSync(uv, ["--version"], {\n    stdio: ["ignore", "pipe", "ignore"],\n    shell: false,\n    encoding: "utf8",\n  });\n  return result.error === undefined &&\n    result.status === 0 &&\n    String(result.stdout || "").trim().startsWith(`uv ${UV_VERSION}`);\n}\n\nasync function ensureUv() {\n  const override = process.env.JAPAN_CAREER_UV_BIN;\n  if (override) {\n    if (!fs.existsSync(override)) throw new Error("JAPAN_CAREER_UV_BIN does not exist");\n    return override;\n  }\n  const existing = privateUvPath();\n  if (fs.existsSync(existing) && uvVersionMatches(existing)) return existing;\n  return installUv();\n}\n\nfunction launcherCandidates() {\n  const names = process.platform === "win32"\n    ? [`${PACKAGE}.exe`, `${PACKAGE}.cmd`, PACKAGE]\n    : [PACKAGE];\n  return names.map((name) => path.join(TOOL_BIN_DIR, name));\n}\n\nfunction findLauncher() {\n  return launcherCandidates().find((candidate) => fs.existsSync(candidate)) || null;\n}\n\nfunction markerIsCurrent() {\n  const launcher = findLauncher();\n  if (!launcher || !fs.existsSync(MARKER)) return false;\n  try {\n    const marker = JSON.parse(fs.readFileSync(MARKER, "utf8"));\n    return marker.package === PACKAGE &&\n      marker.version === version &&\n      marker.uv === UV_VERSION;\n  } catch {\n    return false;\n  }\n}\n\nfunction runtimeEnvironment() {\n  return {\n    ...process.env,\n    UV_TOOL_DIR: TOOL_DIR,\n    UV_TOOL_BIN_DIR: TOOL_BIN_DIR,\n    UV_PYTHON_INSTALL_DIR: PYTHON_DIR,\n    UV_CACHE_DIR: CACHE_DIR,\n    UV_MANAGED_PYTHON: "1",\n    UV_NO_MODIFY_PATH: "1",\n    UV_NO_PROGRESS: "1",\n    UV_ISOLATED: "1",\n  };\n}\n\nasync function installPythonRuntime() {\n  fs.mkdirSync(RUNTIME_ROOT, { recursive: true });\n  const uv = await ensureUv();\n\n  fs.rmSync(TOOL_DIR, { recursive: true, force: true });\n  fs.rmSync(TOOL_BIN_DIR, { recursive: true, force: true });\n  fs.mkdirSync(TOOL_BIN_DIR, { recursive: true });\n\n  run(uv, ["tool", "install", "--force", "--python", "3.13", SPEC], {\n    env: runtimeEnvironment(),\n  });\n  const launcher = findLauncher();\n  if (!launcher) {\n    throw new Error("private Python runtime installed without a japan-career-agent launcher");\n  }\n  fs.writeFileSync(MARKER, `${JSON.stringify({\n    package: PACKAGE,\n    version,\n    uv: UV_VERSION,\n  }, null, 2)}\\n`, { encoding: "utf8", mode: 0o600 });\n  fs.rmSync(CACHE_DIR, { recursive: true, force: true });\n  return launcher;\n}\n\nasync function ensureRuntime(options = {}) {\n  if (!options.force && markerIsCurrent()) return findLauncher();\n  return installPythonRuntime();\n}\n\nmodule.exports = {\n  PACKAGE,\n  RUNTIME_ROOT,\n  SPEC,\n  UV_ARCHIVES,\n  UV_VERSION,\n  ensureRuntime,\n  platformArchive,\n};\n')
write("packaging/npm/bin/cli.js", '#!/usr/bin/env node\n"use strict";\n\nconst { spawnSync } = require("node:child_process");\nconst { ensureRuntime, PACKAGE } = require("../lib/runtime");\n\nasync function main() {\n  let launcher;\n  try {\n    launcher = await ensureRuntime();\n  } catch (error) {\n    process.stderr.write(\n      `${PACKAGE}: local runtime setup failed: ${error.message}\\n` +\n      `Re-run "npm install -g ${PACKAGE}" after checking network access and permissions.\\n`\n    );\n    process.exit(1);\n  }\n\n  const result = spawnSync(launcher, process.argv.slice(2), {\n    stdio: "inherit",\n    shell: false,\n  });\n  if (result.error) {\n    process.stderr.write(`${PACKAGE}: could not start the installed runtime: ${result.error.message}\\n`);\n    process.exit(1);\n  }\n  process.exit(result.status === null ? 1 : result.status);\n}\n\nmain();\n')
write("packaging/npm/bin/install-runtime.js", '#!/usr/bin/env node\n"use strict";\n\nconst { ensureRuntime, PACKAGE } = require("../lib/runtime");\n\nasync function main() {\n  process.stdout.write(`${PACKAGE}: preparing its private runtime...\\n`);\n  try {\n    await ensureRuntime({ force: true });\n  } catch (error) {\n    process.stderr.write(`${PACKAGE}: install failed: ${error.message}\\n`);\n    process.exit(1);\n  }\n  process.stdout.write(`${PACKAGE}: ready. Run "${PACKAGE}".\\n`);\n}\n\nmain();\n')
write("packaging/npm/README.md", '# japan-career-agent (npm)\n\nSelf-contained npm installer for [japan-career-agent](https://github.com/younnieCutler/japan-career-agent).\n\n```bash\nnpm install -g japan-career-agent\njapan-career-agent\n```\n\nThat is the normal installation path. The user does not need to install Python, uv, or pipx.\n\n## What happens during install\n\nThe npm package has no npm runtime dependencies. Its `postinstall` step:\n\n1. selects a pinned uv 0.12.7 archive for the current x64/arm64 macOS, Linux, or Windows platform;\n2. downloads it only from uv\'s official GitHub release and verifies the hard-coded SHA-256 digest;\n3. stores uv under this npm package\'s private `.runtime/` directory;\n4. uses that private uv with managed-Python-only settings to install the exact matching\n   `japan-career-agent` PyPI release into the same private runtime.\n\nIt does not run a downloaded shell installer, use global pip, or modify an existing Python\nenvironment. npm\'s own global command shim is the only PATH entry created by the normal install.\n\nIf npm lifecycle scripts were intentionally disabled, the first `japan-career-agent` invocation\nrepairs the same private runtime before handing over.\n\n## One-off and direct alternatives\n\n```bash\nnpx japan-career-agent\nuvx japan-career-agent\nuv tool install japan-career-agent\npipx install japan-career-agent\n```\n\n`npx` uses the same self-contained npm package in its temporary cache. The uv/pipx commands are\nadvanced direct-Python alternatives, not prerequisites.\n\nCareer data stays on the machine. Nothing is uploaded.\n\nMIT licensed.\n')
write("packaging/npm/THIRD_PARTY_NOTICES.md", '# Third-party notices\n\nThe npm package does not bundle uv in its registry tarball. During installation it downloads the\nplatform-specific uv 0.12.7 binary directly from the official\n[Astral uv release](https://github.com/astral-sh/uv/releases/tag/0.12.7), verifies the pinned\nSHA-256 digest, and keeps that binary inside the npm package\'s private runtime directory.\n\nuv is distributed by Astral under the MIT License or the Apache License 2.0. See the upstream\nrepository for its source and license texts: https://github.com/astral-sh/uv\n')
write("scripts/test_npm_bootstrapper.py", '#!/usr/bin/env python3\n"""Hold the npm package to the self-contained global-install contract."""\n\nfrom __future__ import annotations\n\nimport json\nimport os\nimport re\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\nimport unittest\nfrom pathlib import Path\n\n\nROOT = Path(__file__).resolve().parents[1]\nNPM_DIR = ROOT / "packaging" / "npm"\nPACKAGE_JSON = NPM_DIR / "package.json"\nCLI = NPM_DIR / "bin" / "cli.js"\nRUNTIME = NPM_DIR / "lib" / "runtime.js"\nINSTALL_TIME_HOOKS = ("preinstall", "install", "postinstall", "preuninstall", "postuninstall", "prepare")\n\n\ndef _package() -> dict:\n    return json.loads(PACKAGE_JSON.read_text(encoding="utf-8"))\n\n\ndef _release_version() -> str:\n    return json.loads((ROOT / ".claude-plugin" / "plugin.json").read_text(encoding="utf-8"))["version"]\n\n\nclass NpmBootstrapperContractTests(unittest.TestCase):\n    def test_only_install_hook_prepares_the_private_runtime(self) -> None:\n        scripts = _package().get("scripts", {})\n        present = {name: scripts[name] for name in INSTALL_TIME_HOOKS if name in scripts}\n        self.assertEqual(present, {"postinstall": "node bin/install-runtime.js"})\n\n    def test_ships_only_bootstrap_code_not_generated_runtime(self) -> None:\n        package = _package()\n        self.assertEqual(\n            sorted(package["files"]),\n            [\n                "README.md",\n                "THIRD_PARTY_NOTICES.md",\n                "bin/cli.js",\n                "bin/install-runtime.js",\n                "lib/runtime.js",\n            ],\n        )\n        self.assertEqual(package["bin"], {"japan-career-agent": "bin/cli.js"})\n        self.assertNotIn(".runtime", package["files"])\n        self.assertEqual(package.get("dependencies", {}), {})\n\n    def test_version_matches_the_release(self) -> None:\n        self.assertEqual(_package()["version"], _release_version())\n\n    def test_identity_matches_the_python_package(self) -> None:\n        package = _package()\n        self.assertEqual(package["name"], "japan-career-agent")\n        self.assertEqual(package["license"], "MIT")\n\n    def test_private_runtime_is_pinned_and_checksum_guarded(self) -> None:\n        source = RUNTIME.read_text(encoding="utf-8")\n        self.assertIn(\'const UV_VERSION = "0.12.7";\', source)\n        self.assertNotIn("/latest/", source)\n        self.assertNotIn("pipx", source)\n        self.assertNotIn("pip install", source)\n        self.assertGreaterEqual(len(set(re.findall(r\'[0-9a-f]{64}\', source))), 8)\n        self.assertIn("checksum mismatch", source)\n        self.assertIn("UV_MANAGED_PYTHON", source)\n        self.assertIn("UV_TOOL_DIR", source)\n        self.assertIn("UV_PYTHON_INSTALL_DIR", source)\n\n    def test_launcher_uses_only_the_private_runtime(self) -> None:\n        source = CLI.read_text(encoding="utf-8")\n        self.assertIn("ensureRuntime", source)\n        self.assertNotIn("pipx", source)\n        self.assertNotIn("isAvailable", source)\n        self.assertNotIn("RUNNERS", source)\n\n    @unittest.skipIf(shutil.which("npm") is None, "npm is not available")\n    @unittest.skipIf(\n        sys.platform == "win32",\n        "the local no-network fixture uses a POSIX shell stub; Windows is covered by the repository CI contracts",\n    )\n    def test_global_npm_install_needs_no_preinstalled_python_runner(self) -> None:\n        """Install exactly as a user does, with a fake private uv replacing network access.\n\n        The fake uv only implements `uv tool install`; if the npm launcher still probes PATH for uv,\n        pipx, or Python this test cannot pass. The generated Python launcher exits 42 so argument and\n        exit-code forwarding are observable through npm\'s global shim.\n        """\n        with tempfile.TemporaryDirectory(prefix="japan-career-npm-global-") as temporary:\n            root = Path(temporary)\n            prefix = root / "prefix"\n            cache = root / "npm-cache"\n            stub = root / "uv"\n            recorded = root / "argv.txt"\n            stub.write_text(\n                "#!/bin/sh\\n"\n                \'if [ "$1" = "--version" ]; then echo "uv 0.12.7"; exit 0; fi\\n\'\n                \'if [ "$1" = "tool" ] && [ "$2" = "install" ]; then\\n\'\n                \'  mkdir -p "$UV_TOOL_BIN_DIR"\\n\'\n                \'  cat > "$UV_TOOL_BIN_DIR/japan-career-agent" <<\\\'SH\\\'\\n\'\n                "#!/bin/sh\\n"\n                \'printf "%s\\\\n" "$@" > "$JCA_RECORDED"\\n\'\n                "exit 42\\n"\n                "SH\\n"\n                \'  chmod +x "$UV_TOOL_BIN_DIR/japan-career-agent"\\n\'\n                "  exit 0\\n"\n                "fi\\n"\n                "exit 9\\n",\n                encoding="utf-8",\n            )\n            stub.chmod(0o755)\n\n            npm_env = dict(os.environ)\n            npm_env["npm_config_cache"] = str(cache)\n            npm_env["JAPAN_CAREER_UV_BIN"] = str(stub)\n            npm_env["JCA_RECORDED"] = str(recorded)\n\n            subprocess.run(\n                [shutil.which("npm"), "pack", "--silent", "--pack-destination", str(root), str(NPM_DIR)],\n                cwd=root,\n                capture_output=True,\n                text=True,\n                encoding="utf-8",\n                env=npm_env,\n                check=True,\n            )\n            tarballs = sorted(root.glob("*.tgz"))\n            self.assertEqual(len(tarballs), 1)\n            subprocess.run(\n                [\n                    shutil.which("npm"),\n                    "install",\n                    "-g",\n                    "--silent",\n                    "--no-audit",\n                    "--no-fund",\n                    "--prefix",\n                    str(prefix),\n                    str(tarballs[0]),\n                ],\n                cwd=root,\n                capture_output=True,\n                text=True,\n                encoding="utf-8",\n                env=npm_env,\n                check=True,\n            )\n\n            shim = prefix / "bin" / "japan-career-agent"\n            self.assertTrue(shim.exists(), "npm did not create the global command")\n            markers = list(prefix.rglob("install.json"))\n            self.assertEqual(len(markers), 1, "postinstall did not prepare exactly one private runtime")\n\n            result = subprocess.run(\n                [str(shim), "doctor", "--format", "json"],\n                capture_output=True,\n                text=True,\n                encoding="utf-8",\n                cwd=root,\n                env=npm_env,\n                check=False,\n            )\n            self.assertEqual(result.returncode, 42, result.stderr)\n            forwarded = recorded.read_text(encoding="utf-8")\n            self.assertIn("doctor", forwarded)\n            self.assertIn("--format", forwarded)\n            self.assertIn("json", forwarded)\n\n\nif __name__ == "__main__":\n    unittest.main(verbosity=0)\n')

package_path = ROOT / "packaging/npm/package.json"
package = json.loads(package_path.read_text(encoding="utf-8"))
package["description"] = "Self-contained npm installer for the local-first Japan Career Agent Python runtime."
package["scripts"] = {"postinstall": "node bin/install-runtime.js"}
package["files"] = [
    "bin/cli.js",
    "bin/install-runtime.js",
    "lib/runtime.js",
    "README.md",
    "THIRD_PARTY_NOTICES.md",
]
package.pop("dependencies", None)
package_path.write_text(json.dumps(package, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")

segments = {
    "README.md": ('## Quick start\n\nInstall once, then run the command:\n\n```bash\nnpm install -g japan-career-agent\njapan-career-agent\n```\n\nThat is the complete end-user installation path. The npm package prepares its own private runtime;\nyou do not need to install or configure Python, uv, or pipx. The first zero-argument launch prepares\nonly the empty local career record the GUI needs. It does not infer, approve, or upload a career\nfact. Import or paste the history you already have, then confirm only what you want to keep.\n\nThe explicit `setup`, `guided`, `ui`, and other CLI commands remain available for terminal or\nautomation workflows. In a plugin host, use a normal request:\n\n```text\nI want to start preparing for a job change in Japan.\nCompare this JD with my experience and keep unconfirmed points as Unknown.\nHelp me prepare for next week\'s interview.\nReview this 職務経歴書 without inventing evidence.\n```\n\n## Install\n\n### Install once\n\nThe normal installation is intentionally two lines:\n\n```bash\nnpm install -g japan-career-agent\njapan-career-agent\n```\n\nDuring `npm install`, the package downloads one pinned uv binary from uv\'s official immutable\nrelease, verifies its SHA-256 checksum, and uses it only inside the npm package to prepare a managed\nPython and the exact matching PyPI release. It does not write to system Python, global pip, or your\nPython environments. npm\'s own global command shim is the only PATH entry this installation needs.\n\n**The canonical product runtime is still Python**. npm owns only installation and the command\nentrypoint; CLI, GUI, plugins, approval, and the Career Vault all reach the same Python package.\n\n### One-off and direct alternatives\n\nFor a one-off npm run, or if you already manage Python tools yourself:\n\n```bash\nnpx japan-career-agent\nuvx japan-career-agent\nuv tool install japan-career-agent\npipx install japan-career-agent\n```\n\n`npx` uses the same self-contained npm package in its temporary cache. `uvx`, `uv tool`, and `pipx`\nare advanced direct-Python alternatives; they are not prerequisites for the global npm install.\n\n### Enhanced integrations\n\nOptional. If you already use Claude Code or Codex, the plugin adds skill discovery, a host-native\nconversational workflow, and host status context on top of the same core.\n\n```bash\nclaude plugin marketplace add younnieCutler/japan-career-agent\nclaude plugin install japan-career-agent@japan-career-agent\n```\n\n```bash\ncodex plugin marketplace add younnieCutler/japan-career-agent\ncodex plugin add japan-career-agent@japan-career-agent\n```\n\nA plugin never holds its own copy of your career facts. The Vault, the evidence ledger, approval and\nrecovery, readiness, JD evidence selection, the deterministic document gate and HTML rendering all\nwork with no host installed; the plugin changes how you reach them, never what they say.\n[The capability matrix](https://github.com/younnieCutler/japan-career-agent/blob/main/docs/CAPABILITY_MATRIX.md)\nlists which is which.\n', r"## Quick start\n.*?(?=\n## What it can help with)"),
    "README_ko.md": ('## Quick Start\n\n한 번 설치한 뒤 실행하면 됩니다.\n\n```bash\nnpm install -g japan-career-agent\njapan-career-agent\n```\n\n사용자가 준비할 것은 여기까지입니다. npm 패키지가 자기 전용 runtime을 내부에서 준비하므로 Python,\nuv, pipx를 따로 설치하거나 설정할 필요가 없습니다. 인자 없이 처음 실행할 때는 GUI에 필요한 빈 로컬\n경력 기록만 준비하며, 경력 사실을 추정·확정·업로드하지 않습니다. 기존 이력서·職務経歴書를 가져오거나\n붙여넣고 남길 내용만 직접 확정하면 됩니다.\n\n터미널이나 자동화가 필요하면 기존 `setup`, `guided`, `ui`와 나머지 CLI 명령을 그대로 쓸 수 있습니다.\nplugin host에서는 평소 말하듯 요청하면 됩니다.\n\n```text\n일본 이직 준비를 시작하고 싶어.\n이 JD와 내 경력을 비교하고, 확인되지 않은 내용은 Unknown으로 남겨줘.\n다음 주 면접을 준비하고 싶어.\n이 職務経歴書를 검토하되 없는 경력은 만들지 마.\n```\n\n## 설치\n\n### 한 번 설치하기\n\n일반 사용자의 설치 경로는 의도적으로 두 줄입니다.\n\n```bash\nnpm install -g japan-career-agent\njapan-career-agent\n```\n\n`npm install` 중 패키지는 uv의 공식 immutable release에서 고정된 uv 바이너리 하나만 내려받고\nSHA-256을 검증합니다. 그 uv는 npm 패키지 내부에서만 managed Python과 동일 버전의 PyPI\n`japan-career-agent`를 준비합니다. 시스템 Python, global pip, 기존 Python 환경은 변경하지 않습니다.\nPATH에 추가되는 것은 npm이 만드는 `japan-career-agent` 명령뿐입니다.\n\n**canonical 제품 runtime은 계속 Python**입니다. npm은 설치와 진입점만 담당하며 CLI, GUI, plugin,\n승인 경계와 Career Vault는 모두 같은 Python 패키지에 도달합니다.\n\n### 일회성 실행과 직접 설치 대안\n\n한 번만 실행하거나 Python 도구를 직접 관리하고 싶다면 다음 경로도 유지됩니다.\n\n```bash\nnpx japan-career-agent\nuvx japan-career-agent\nuv tool install japan-career-agent\npipx install japan-career-agent\n```\n\n`npx`는 임시 npm cache 안에서 같은 self-contained 패키지를 사용합니다. `uvx`, `uv tool`, `pipx`는\n고급 사용자를 위한 direct-Python 대안일 뿐, global npm 설치의 사전 요구사항이 아닙니다.\n\n### 추가로 쓸 수 있는 통합\n\n선택 사항입니다. 이미 Claude Code나 Codex를 쓰고 있다면, plugin이 같은 core 위에 skill discovery,\nhost native 대화 workflow, host의 status context를 얹어 줍니다.\n\n```bash\nclaude plugin marketplace add younnieCutler/japan-career-agent\nclaude plugin install japan-career-agent@japan-career-agent\n```\n\n```bash\ncodex plugin marketplace add younnieCutler/japan-career-agent\ncodex plugin add japan-career-agent@japan-career-agent\n```\n\nplugin이 경력 사실을 따로 보관하는 일은 없습니다. Vault, 근거 ledger, 승인과 복구, readiness,\nJD별 근거 선택, 결정적 문서 게이트, HTML 생성은 모두 host 없이 동작합니다. plugin이 바꾸는 것은\n도달하는 방식이지 답의 내용이 아닙니다. 어느 쪽이 어느 쪽인지는\n[capability matrix](https://github.com/younnieCutler/japan-career-agent/blob/main/docs/CAPABILITY_MATRIX.md)에\n정리돼 있습니다.\n', r"## Quick Start\n.*?(?=\n## 할 수 있는 일)"),
    "README_ja.md": ('## Quick Start\n\n一度インストールしたら、そのまま起動できます。\n\n```bash\nnpm install -g japan-career-agent\njapan-career-agent\n```\n\nユーザー側の準備はこれだけです。npm パッケージが専用 runtime を内部で準備するため、Python、uv、\npipx を別途インストール・設定する必要はありません。引数なしで初めて起動すると、GUI に必要な\n空のローカル経歴記録だけを準備し、経歴の事実を推測・確定・アップロードすることはありません。\n手元の履歴書・職務経歴書を読み込むか貼り付け、残したい内容だけを自分で確定できます。\n\nターミナルや自動化が必要な場合は、既存の `setup`、`guided`、`ui` とその他の CLI コマンドを\nそのまま使えます。plugin host では普段の言葉で依頼するだけです。\n\n```text\n日本での転職準備を始めたいです。\nこのJDと私の経験を比較し、確認できないことはUnknownのままにしてください。\n来週の面接を準備したいです。\nこの職務経歴書を、ない根拠を足さずにレビューしてください。\n```\n\n## インストール\n\n### 一度インストールする\n\n通常のインストール経路は意図的に2行だけです。\n\n```bash\nnpm install -g japan-career-agent\njapan-career-agent\n```\n\n`npm install` 中に、パッケージは uv の公式 immutable release から固定された uv バイナリを1つだけ\n取得し、SHA-256 を検証します。その uv は npm パッケージ内部だけで managed Python と同じ\nバージョンの PyPI `japan-career-agent` を準備します。システム Python、global pip、既存の\nPython 環境は変更しません。PATH に追加されるのは npm が作る `japan-career-agent` コマンドだけです。\n\n**canonical な製品 runtime は引き続き Python** です。npm はインストールと入口だけを担当し、\nCLI、GUI、plugin、承認境界、Career Vault はすべて同じ Python パッケージに到達します。\n\n### 一度だけの実行と直接インストールの代替\n\n一度だけ実行する場合や Python ツールを自分で管理する場合は、次の経路も残します。\n\n```bash\nnpx japan-career-agent\nuvx japan-career-agent\nuv tool install japan-career-agent\npipx install japan-career-agent\n```\n\n`npx` は一時 npm cache 内で同じ self-contained パッケージを使います。`uvx`、`uv tool`、`pipx`\nは上級者向けの direct-Python 代替であり、global npm インストールの前提条件ではありません。\n\n### 追加で使える統合\n\n任意です。すでに Claude Code か Codex を使っているなら、plugin が同じ core の上に skill discovery、\nhost native な会話 workflow、host の status context を追加します。\n\n```bash\nclaude plugin marketplace add younnieCutler/japan-career-agent\nclaude plugin install japan-career-agent@japan-career-agent\n```\n\n```bash\ncodex plugin marketplace add younnieCutler/japan-career-agent\ncodex plugin add japan-career-agent@japan-career-agent\n```\n\nplugin がキャリアの事実を独自に持つことはありません。Vault、根拠の ledger、承認と復旧、readiness、\nJD ごとの根拠選択、決定的な書類ゲート、HTML 生成はいずれも host 無しで動きます。plugin が変えるの\nは到達の仕方だけで、答えの中身ではありません。どれがどちらかは\n[capability matrix](https://github.com/younnieCutler/japan-career-agent/blob/main/docs/CAPABILITY_MATRIX.md)\nに一覧があります。\n', r"## Quick Start\n.*?(?=\n## できること)"),
}
for rel, (replacement, pattern) in segments.items():
    path = ROOT / rel
    text = path.read_text(encoding="utf-8")
    updated, count = re.subn(pattern, replacement.rstrip(), text, count=1, flags=re.S)
    if count != 1:
        raise SystemExit(f"could not replace install section in {rel}")
    path.write_text(updated, encoding="utf-8", newline="\n")

check_path = ROOT / "scripts/check_readme_consistency.py"
check = check_path.read_text(encoding="utf-8")
old_install = """INSTALL_ORDER = (
    "npx japan-career-agent",
    "uvx japan-career-agent",
    "uv tool install japan-career-agent",
    "pipx install japan-career-agent",
    "claude plugin install japan-career-agent@japan-career-agent",
    "codex plugin add japan-career-agent@japan-career-agent",
)
"""
new_install = """GLOBAL_NPM_PAIR = re.compile(
    r"npm install -g japan-career-agent\\s*\\njapan-career-agent"
)
INSTALL_ORDER = (
    "npm install -g japan-career-agent",
    "npx japan-career-agent",
    "uvx japan-career-agent",
    "uv tool install japan-career-agent",
    "pipx install japan-career-agent",
    "claude plugin install japan-career-agent@japan-career-agent",
    "codex plugin add japan-career-agent@japan-career-agent",
)
"""
if old_install not in check:
    raise SystemExit("README install-order anchor changed")
check = check.replace(old_install, new_install, 1)
needle = """        if FIRST_RUN_IS_INIT.search(text):
            errors.append(f"{path.name}: the first command shown is `init`; the first run is zero-argument")
        position = -1
"""
replacement = """        if FIRST_RUN_IS_INIT.search(text):
            errors.append(f"{path.name}: the first command shown is `init`; the first run is zero-argument")
        if not GLOBAL_NPM_PAIR.search(text):
            errors.append(
                f"{path.name}: quick start must show `npm install -g japan-career-agent` "
                "followed by `japan-career-agent`"
            )
        position = -1
"""
if needle not in check:
    raise SystemExit("README pair-check anchor changed")
check_path.write_text(check.replace(needle, replacement, 1), encoding="utf-8", newline="\n")

release_path = ROOT / ".github/workflows/release.yml"
release = release_path.read_text(encoding="utf-8")
old_release = """          python -m pip install --quiet pipx
          workspace="$(mktemp -d)"
          cd "$workspace"
          npx --yes "japan-career-agent@$VERSION" setup --track chuto --target-role "Platform Engineer" --format json > setup.json
          python -c "import json,sys; d=json.load(open('setup.json')); sys.exit(0 if d.get('mode')=='setup' else 'setup did not return setup mode')"
          npx --yes "japan-career-agent@$VERSION" guided --format json > guided.json
          python -c "import json,sys; d=json.load(open('guided.json')); sys.exit(0 if d.get('guided',{}).get('available_actions') else 'guided returned no actions')"
"""
new_release = """          workspace="$(mktemp -d)"
          prefix="$workspace/npm-global"
          npm install -g --prefix "$prefix" "japan-career-agent@$VERSION"
          agent="$prefix/bin/japan-career-agent"
          test -x "$agent"
          cd "$workspace"
          "$agent" setup --track chuto --target-role "Platform Engineer" --format json > setup.json
          python -c "import json,sys; d=json.load(open('setup.json')); sys.exit(0 if d.get('mode')=='setup' else 'setup did not return setup mode')"
          "$agent" guided --format json > guided.json
          python -c "import json,sys; d=json.load(open('guided.json')); sys.exit(0 if d.get('guided',{}).get('available_actions') else 'guided returned no actions')"
"""
if old_release not in release:
    raise SystemExit("release npm smoke anchor changed")
release = release.replace(old_release, new_release, 1)
release = release.replace(
    "# The npm channel is a bootstrapper, not a copy of the runtime, so installing it proves\n"
    "# nothing on its own. Running the two commands the README's quick start prints is what\n"
    "# checks that the documented first five minutes work against what was just published.\n",
    "# The npm channel prepares a private runtime during global install. Verify the exact public\n"
    "# contract: one npm install, then the generated japan-career-agent command with no uv/pipx setup.\n",
    1,
)
release_path.write_text(release, encoding="utf-8", newline="\n")

pyproject = ROOT / "pyproject.toml"
py = pyproject.read_text(encoding="utf-8")
if 'version = "2.26.0"' not in py:
    raise SystemExit("expected 2.26.0 pyproject version")
pyproject.write_text(py.replace('version = "2.26.0"', 'version = "2.27.0"', 1), encoding="utf-8", newline="\n")

changelog = ROOT / "CHANGELOG.md"
change = changelog.read_text(encoding="utf-8")
entry = """## [2.27.0] - 2026-09-04

- Make `npm install -g japan-career-agent` the self-contained default install. npm now fetches a pinned uv 0.12.7 archive from the official immutable release, verifies its SHA-256 digest, and uses a package-private managed Python to install the exact matching PyPI runtime; users do not need to preinstall Python, uv, or pipx, and existing Python environments are not modified.
- Make the installed npm command use only that private runtime, keep `npx` and direct uv/pipx paths as optional alternatives, and verify the real global-install contract in repository and post-publish smoke tests.

"""
if "## [2.27.0]" not in change:
    change = change.replace("# Changelog\n\n", "# Changelog\n\n" + entry, 1)
changelog.write_text(change, encoding="utf-8", newline="\n")

for rel in ("docs/upgrading.md", "docs/upgrading_ko.md", "docs/upgrading_ja.md"):
    path = ROOT / rel
    text = path.read_text(encoding="utf-8")
    if "2.26.0" not in text:
        raise SystemExit(f"{rel} has no 2.26.0 source marker")
    path.write_text(text.replace("2.26.0", "2.27.0", 1), encoding="utf-8", newline="\n")

print("npm global install patch applied")
